 $Version.release_name = "Multi-Agent Collaboration"
 $Version.status = "part_b_installed"
 $Version.installed_at = (Get-Date).ToString("o")
 $Version.next_planned_milestone = "1.6 Part C Dashboard, Certification, and Release"
 $Version | ConvertTo-Json -Depth 40 | Set-Content -LiteralPath $VersionPath -Encoding UTF8
}
